#define main legacy_main
#include "channelShuffle-cuda/main.cu"
#undef main
#include <vector>
int main(){int n=4*32*64,repeat=10;std::vector<float>x(n),out(n),expected(n),values;for(int i=0;i<n;i++)x[i]=float(i)/n;float *dx,*dy;cudaMalloc(&dx,n*4);cudaMalloc(&dy,n*4);cudaMemcpy(dx,x.data(),n*4,cudaMemcpyHostToDevice);auto run=[&](int phase){if(phase==0)ChannelShuffleNHWCKernel<float,32><<<256,256>>>(4,8,dx,dy);else ChannelShuffleNCHWKernel<float,false><<<dim3(1,4,32),256>>>(4,8,64,dx,dy);};run(0);run(1);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;
for(int trial=1;trial<=5;trial++){values.clear();double times[2],total=0.;bool correct=true;for(int phase=0;phase<2;phase++){cudaMemset(dy,0,n*4);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int j=0;j<repeat;j++)run(phase);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;times[phase]=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;total+=times[phase];cudaMemcpy(out.data(),dy,n*4,cudaMemcpyDeviceToHost);long ignored=0;if(phase==0)ChannelShuffleNHWC_cpu(x.data(),4,32,4,n,expected.data(),ignored,1);else ChannelShuffleNCHW_cpu(x.data(),4,32,4,n,expected.data(),ignored,1);correct &=out==expected;values.insert(values.end(),out.begin(),out.end());}char file[32];snprintf(file,sizeof(file),"trial_%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(values.data(),4,values.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.14g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"timing_region\":\"sum_nhwc_nchw_synchronized_loop_means\",\"jit_excluded\":true,\"internal_repeats\":%d,\"subkernel_times_seconds\":[%.14g,%.14g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,total,correct?"true":"false",values.size(),correct?0:1,repeat,times[0],times[1],file,values.size());if(!correct)return 1;}cudaFree(dx);cudaFree(dy);}
